\set ON_ERROR_STOP on
begin;
delete from coverage_rule where document_id = (select id from program_document where id::text like '216bf684%');
with d as (select id, insurance_company_id from program_document where id::text like '216bf684%')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause)
select d.id, d.insurance_company_id, v.pn, v.sc, v.sp, v.vd, v.ct, v.la, v.cl from d cross join (values
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ)','общие-условия','страховой случай острое заболевание обострение травма несчастный случай','conditional','услуги — только по страховому случаю: обращение в срок договора в учреждение из числа предусмотренных договором при остром заболевании, обострении хронического, травме, несчастном случае',null,'Раздел «Программа ДМС» «Страховым случаем является обращение застрахованного лица»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ)','стоматология-приёмы','программа стоматология в базовом пакете','excluded','стоматология НЕ входит в базовый пакет: включается по желанию сотрудника и оплачивается дополнительно из собственных средств',null,'«Программа "Стоматология" включается в пакет ДМС по желанию сотрудника и оплачивается дополнительно»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ) — Стоматология №1','общие-условия','стоматология на базе лпу по направлению страховщика','needs_approval','вариант стоматологии №1 — на базе ЛПУ по направлению страховщика',null,'«варианты стоматологии на базе ЛПУ (по направлению страховщика)  - №1»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ) — Стоматология №2','общие-условия','стоматология на базе лик расширенная','covered','вариант №2 — на базе ЛИК, расширенная (объём — по программе страховщика)',null,'«на базе ЛИК, расширенная - №2»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ) — Стоматология №3','общие-условия','стоматология на базе лик стандарт','covered','вариант №3 — на базе ЛИК, стандарт (объём — по программе страховщика)',null,'«на базе ЛИК, стандарт - №3»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ)','общие-условия','гарантийное письмо при отказе регистратуры','needs_approval','если клиника требует оплатить услуги, входящие в полис — до оплаты связаться со страховой; страховщик оценит ситуацию и направит в ЛПУ ГАРАНТИЙНОЕ ПИСЬМО (контакт-центр 8-800-333-44-19)',null,'«Страховщик оценит ситуацию и направит в ЛПУ гарантийное письмо»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ)','общие-условия','запись на приём контакт-центр личный кабинет регистратура','conditional','запись — через контакт-центр, ЛК застрахованного или в регистратуре клиники (только клиники прямой записи); спорные вопросы решает врач-куратор',null,'«Все спорные вопросы решает врач-куратор»'),
('Прямой договор МЭР (НИУ ВШЭ)','стоматология-приёмы','стоматологические услуги скидка 20%','excluded','по прямому договору МЭР стоматология не покрывается — предоставляется скидка 20%; ортодонтия, ортопедическая стоматология и имплантология исключены даже из скидки','20% скидка','«скидка на стоматологические услуги в размере 20%»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ)','общие-условия','полис путешественника впмж','covered','оформляется без дополнительной оплаты застрахованным по ДМС',null,'«предоставляется дополнительная услуга по оформлению полиса путешественника»'),
('Корпоративный ДМС НИУ ВШЭ (СОГАЗ)','общие-условия','страхование родственников','conditional','родственников можно застраховать в течение 60 дней с даты начала страхования сотрудника, по отдельному договору и за свой счёт',null,'«могут застраховать близких родственников в течение 60 дней»')
) as v(pn, sc, sp, vd, ct, la, cl);
select count(*) as sogaz_web from coverage_rule where document_id = (select id from program_document where id::text like '216bf684%');
commit;
